import { test, expect } from 'e2e';

test('adds a todo', async ({ app, screen, agent }) => {
  await app.open('/todos');
  await agent.act('Add a todo named Buy coffee, and verify it is listed.');
  await expect(screen.getByTestId('todo')).toContainText('Buy coffee');
  await agent.assert('The todo list contains Buy coffee.');
});

import { test } from '@e2e-dev/web';
import { expect, credentials } from 'e2e';

test.setup('authenticate as admin', { sessions: ['admin'] }, async ({ app, screen, session, browser }) => {
  const admin = credentials.user('admin');

  await app.open('/login');
  await screen.getByLabel('Username').fill(admin.username);
  await screen.getByLabel('Password').fill(admin.password);
  await screen.getByRole('button', 'Sign in').tap();

  await expect(browser).toHaveURL('/dashboard');
  await expect(screen.getByRole('status', 'Greeting')).toContainText('admin');

  await session.save('admin');
});

test.setup('authenticate as admin with a cookie', { sessions: ['admin-cookie'] }, async ({ app, screen, session, browser }) => {
  // No secret is filled, so what restores this session keeps its screenshots.
  await app.open('/');
  await browser.setCookies([{ name: 'session', value: 'admin', url: await browser.url(), httpOnly: true }]);
  await app.open('/dashboard');

  await expect(browser).toHaveURL('/dashboard');
  await expect(screen.getByRole('status', 'Greeting')).toContainText('admin');

  await session.save('admin-cookie');
});

import { test } from '@e2e-dev/mobile';
import { expect } from 'e2e';

// Agent steps call the model in e2e.config.ts. Without a key these tests are skipped.
const skip = process.env.AI_GATEWAY_API_KEY ? false : 'set AI_GATEWAY_API_KEY to run agent tests';

test('the agent gets a greeting', { skip }, async ({ app, agent, screen }) => {
  await app.open();

  // The agent works out which field and button to use.
  await agent.act('get the app to greet {name}', { params: { name: 'Grace' } });

  // Pair each agent step with a check that does not depend on the model.
  await expect(screen.getByTestId('greeting')).toHaveText('Hello, Grace!');
  await agent.assert('the app greets Grace by name');
});

test('the agent finds the empty-name error', { skip }, async ({ app, agent, screen }) => {
  await app.open();

  await agent.act('press Greet without typing a name');

  await expect(screen.getByTestId('error')).toHaveText('Enter a name first.');
  await agent.assert('the app asks for a name');
});

import type { E2EConfig } from 'e2e';
import { web } from '@e2e-dev/web';
import { decisionExecutor } from '@e2e-dev/decision';
import { typeSafeAi } from '@ai-sdk/typesafe-ai';
import { openrouter } from '@openrouter/ai-sdk-provider';

export default {
  targets: [{ engine: web(), app: { url: 'http://localhost:3000' } }],
  agents: {
    default: {
      executor: decisionExecutor({
        model: typeSafeAi.decisionModel('jev-latest'),
        textModel: openrouter('inception/mercury-2.5'),
      }),
    },
  },
} satisfies E2EConfig;

/**
 * Host-side secret fill authorization against the node shapes engines
 * project. The Android password field is the case that motivated it: the
 * mobile engine once projected it as a plain textbox, which this policy
 * refuses for a credential's password, so the shape core accepts is pinned
 * here next to the shape it turns away.
 */

import { afterEach, describe, expect, it } from 'vitest';
import type { AgentContext } from '../../src/agent/invocation.ts';
import { authorizeSecretFill } from '../../src/agent/secrets.ts';
import type { ResolvedCredential, ResolvedSecret } from '../../src/config/resolve.ts';
import type { SemanticNode } from '../../src/engine/surface.ts';
import { secretBrand } from '../../src/internal/brands.ts';
import type { Secret } from '../../src/types.ts';
import { credentials, setSecretRegistry } from '../../src/secrets.ts';

const adminPassword: ResolvedSecret = { name: 'admin.password', purpose: 'password', value: 'hunter2' };
const admin: ResolvedCredential = { name: 'admin', username: 'admin@example.com', password: adminPassword };

afterEach(() => {
  setSecretRegistry(undefined);
});

/** The two members `authorizeSecretFill` reads off the runtime, over one registered credential; `resolved` hears each plaintext read. */
function runtime(resolved: string[] = []): AgentContext {
  return {
    config: { allSecrets: new Map([[adminPassword.name, adminPassword]]) },
    secrets: {
      resolve: async (secret: Secret) => {
        resolved.push(secret.name);
        return adminPassword.value;
      },
    },
  } as unknown as AgentContext;
}

function host(): { decisions: string[]; recordPolicy: (name: string, decision: string, code?: string) => void } {
  const decisions: string[] = [];
  return {
    decisions,
    recordPolicy: (name, decision, code) => {
      decisions.push(code === undefined ? `${name}:${decision}` : `${name}:${decision}:${code}`);
    },
  };
}

/**
 * An Android password `EditText` as `@e2e-dev/mobile` projects it: UIAutomator
 * flags it `password` while the class stays the plain one, so the engine
 * derives `secure` and the purpose from the flag and drops the value.
 */
const androidPasswordField: SemanticNode = {
  ref: { id: 'n3', revision: '' },
  role: 'textbox',
  name: 'Password',
  text: 'Password',
  inputPurpose: 'password',
  states: { secure: true },
  testId: 'com.example:id/password',
  rect: { x: 0, y: 270, width: 390, height: 44 },
  selector: 'id=com.example:id/password',
};

/** The same field as the engine projected it before it read the flag: an open textbox carrying the typed value. */
const asPlainTextbox: SemanticNode = {
  ref: { id: 'n3', revision: '' },
  role: 'textbox',
  name: 'Password',
  text: 'Password',
  value: 'hunter2',
  testId: 'com.example:id/password',
  rect: { x: 0, y: 270, width: 390, height: 44 },
  selector: 'id=com.example:id/password',
};

describe('authorizeSecretFill', () => {
  it('lets a credential password into an Android password field as the mobile engine projects it', async () => {
    setSecretRegistry({ credentials: new Map([[admin.name, admin]]), secrets: new Map(), allSecrets: new Map([[adminPassword.name, adminPassword]]) });
    const recorder = host();
    await expect(authorizeSecretFill(recorder, runtime(), credentials.user('admin').password, androidPasswordField)).resolves.toBe(
      'hunter2',
    );
    expect(recorder.decisions).toEqual(['secret.fill:allowed']);
  });

  it('refuses the same field projected as a plain textbox, the shape before the mobile fix', async () => {
    setSecretRegistry({ credentials: new Map([[admin.name, admin]]), secrets: new Map(), allSecrets: new Map([[adminPassword.name, adminPassword]]) });
    const recorder = host();
    await expect(authorizeSecretFill(recorder, runtime(), credentials.user('admin').password, asPlainTextbox)).rejects.toMatchObject({
      code: 'POLICY_DENIED',
      message: 'field purpose none is incompatible with secret purpose password',
    });
    expect(recorder.decisions).toEqual(['secret.purpose:denied:POLICY_DENIED']);
  });

  it('judges the purpose by the config, not by what a handle claims', async () => {
    const claimsGeneric: Secret = Object.freeze({ name: adminPassword.name, purpose: 'generic-secret', [secretBrand]: true as const });
    const recorder = host();
    const resolved: string[] = [];
    await expect(authorizeSecretFill(recorder, runtime(resolved), claimsGeneric, asPlainTextbox)).rejects.toMatchObject({
      code: 'POLICY_DENIED',
      message: 'field purpose none is incompatible with secret purpose password',
    });
    expect(recorder.decisions).toEqual(['secret.purpose:denied:POLICY_DENIED']);
    expect(resolved).toEqual([]);
  });

  it.each([
    { sink: 'a disabled password field', node: { ...androidPasswordField, states: { secure: true, disabled: true } }, message: 'the target field is disabled' },
    { sink: 'a button', node: { ...androidPasswordField, role: 'button', states: {} }, message: 'the target is not an editable input (role button)' },
  ])('refuses $sink before reading the plaintext', async ({ node, message }) => {
    setSecretRegistry({ credentials: new Map([[admin.name, admin]]), secrets: new Map(), allSecrets: new Map([[adminPassword.name, adminPassword]]) });
    const recorder = host();
    const resolved: string[] = [];
    await expect(authorizeSecretFill(recorder, runtime(resolved), credentials.user('admin').password, node)).rejects.toMatchObject({
      code: 'POLICY_DENIED',
      message,
    });
    expect(recorder.decisions).toEqual(['secret.sink:denied:POLICY_DENIED']);
    expect(resolved).toEqual([]);
  });
});

